from pathlib import Path
p=Path('outputs/Mechanical_Design_App/index.html');s=p.read_text(encoding='utf-8').replace('LOCAL BETA 0.7','LOCAL BETA 0.8')
s=s.replace('<h3>Proposed design revision</h3>', '''<h3>Generate proposed meshes</h3><p class="muted">Render the constrained pilot revision with local OpenSCAD. This can take up to a minute. Both meshes are checked for closed edges; component clearance and physical fit remain unvalidated.</p><div class="bar"><button id="buildRevision">Generate & show proposal</button><button id="downloadBuild" class="secondary" disabled>Download matching revision package</button></div><p id="buildStatus" role="status" class="muted">No generated proposal in this session.</p><div class="bar"><button id="viewBaseline" class="secondary">Show baseline v2</button><button id="viewProposal" class="secondary" disabled>Show generated proposal</button></div><h3>Source-only design revision</h3>''')
s=s.replace('Only the pilot changes; this viewer stays at baseline v2.', 'Only the pilot changes. Source-only export does not regenerate the viewer; use Generate & show proposal above.')
s=s.replace('Tray and faceplate stay at clearance v2.', 'The viewer starts at clearance v2. Generate a proposal to view its newly rendered meshes.')
s=s.replace('not the manufacturing meshes.', 'independently of the manufacturing meshes. The model label identifies the mesh revision being displayed.')
s=s.replace('let previewTimer;let previewRevision=0;', 'let previewTimer;let previewRevision=0;let generatedBuild=null;')
s=s.replace('function markDirty(){dirty=true;', "function markDirty(){dirty=true;generatedBuild=null;$('downloadBuild').disabled=true;$('viewProposal').disabled=true;$('buildStatus').textContent='Inputs changed. Generate the revised meshes again.';window.dispatchEvent(new CustomEvent('assembly-model',{detail:null}));")
code='''
function showModel(assembly){window.dispatchEvent(new CustomEvent('assembly-model',{detail:assembly}))}
$('viewBaseline').onclick=()=>showModel(null);
$('viewProposal').onclick=()=>{if(generatedBuild)showModel(generatedBuild.assembly)};
$('buildRevision').onclick=()=>safe(async()=>{const draft=payload(),snapshot=JSON.stringify(draft);$('buildRevision').disabled=true;$('buildStatus').textContent='Rendering tray and faceplate with OpenSCAD…';try{const result=await api('build',draft);if(JSON.stringify(payload())!==snapshot){$('buildStatus').textContent='Render completed for older inputs. Generate again for current inputs.';return}generatedBuild=result;$('viewProposal').disabled=false;$('downloadBuild').disabled=false;showModel(result.assembly);$('buildStatus').textContent=`Showing ${result.assembly.revision}. Both meshes passed edge-closure checks. Physical fit remains unvalidated.${result.cached?' Reused matching cached render.':''}`;}catch(e){$('buildStatus').textContent=e.message;throw e}finally{$('buildRevision').disabled=false}});
$('downloadBuild').onclick=()=>safe(async()=>{if(!generatedBuild)throw Error('Generate the current revision first.');const response=await fetch('/api/build-bundle',{method:'POST',headers:{'Content-Type':'application/json','X-App-Token':token},body:JSON.stringify({id:generatedBuild.id})});if(!response.ok){const e=await response.json();throw Error(e.error)}const url=URL.createObjectURL(await response.blob()),a=document.createElement('a');a.href=url;a.download='pi4-rendered-revision-'+generatedBuild.id.slice(0,8)+'.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
'''
s=s.replace("$('designExport').onclick=",code+"\n$('designExport').onclick=")
p.write_text(s,encoding='utf-8')
